      "features": {
        "face_shape": "Exact match to reference image, retaining slight real-world facial asymmetry and natural jawline",
        "eyes": "Exact match to reference image, including exact eye color, normally proportioned with clear window catchlights",
        "nose": "Exact match to reference image",
        "lips": "Exact match to reference image, naturally closed, without obvious smile",
        "skin": "Exact match to reference image, visually and tactilely human: smooth but not waxy, extremely subtle pores, tiny facial hairs, local tone variation",
        "hair": "Exact match to reference image's base hair color and style"
      }
    },
    "camera_and_composition": {
      "placement": "Extreme close-up, slightly below face level or upper-chest height",
      "angle": "Mild upward angle",
      "lens": "24–28mm full-frame-equivalent smartphone front camera",
      "perspective_effects": "Wide-angle foreground distortion (enlarged lower-right sleeve), slight framing drift",
      "depth_of_field": "Background gently out of focus but retains believable room geometry"
    },
    "subject_and_posing": {
      "body_type": "Naturally slender",
      "pose": "Seated beside a window, leaning noticeably forward toward the lens, head tilted gently toward image-right, chin slightly raised, uneven shoulder height",
      "expression": "Looking directly into the lens, relaxed eyelids, unposed appearance as if just leaned closer to glance at the phone"
    },
    "styling": {
      "makeup": {
        "style": "Thin, low-saturation East-Asian costume-drama-inspired",
        "details": "Soft gray-brown brows, extremely fine brown-black inner eyeliner, light taupe mixed with muted dusty-rose eyeshadow, naturally elongated but not overly dense eyelashes, almost no visible nose contour, trace of cool-pink cheek color, softly blurred muted rose-pink lips. Avoid heavy contouring and obvious powder highlighter."
      },
      "hair_styling": {
        "style": "Long, mostly straight, lightly tied or half-pinned behind head",
        "details": "Irregular wispy long bangs, several long strands beside cheeks",
        "texture": "Not commercially perfect; many tiny flyaway hairs around crown, temples, ears, and silhouette catching bright backlight (thin silver-white lines)"
      },
      "clothing": {
        "garment": "Loose ivory or creamy off-white overlapping classical robe/Han-inspired garment",
        "fabric": "Soft, lightweight, faintly translucent, lightly wrinkled",
        "fit": "Broad sleeves, deep V-shaped neckline naturally slipped off shoulders due to gravity and forward-leaning posture",
        "details": "Small visible portion of desaturated pale blue-gray or mint-gray fabric sash at the waist. Exposed skin strictly within natural limits (face, neck, collarbones, upper-chest, minimal upper-arm)."
      },
      "accessories": {
        "left_side": "Delicate pale petals with a few pastel blue and soft pink beads",
        "right_side": "Fine gold-toned structure with pearls and several small teardrop-shaped dangling beads",
        "constraints": "Lightweight and refined. No visible necklace or large modern statement jewelry"
      }
    },
    "lighting_and_environment": {
      "lighting_type": "Physical light, genuine daylight",
      "light_source": "Real window located upper-left or upper-left-rear",
      "highlights": "Slightly cool-white direct sunlight on hair, ear area, left shoulder, collarbones, and foreground sleeve. Mild highlight clipping on left shoulder",
      "shadows": "Realistic soft indoor shadows beneath chin and along neck. Faint cyan-gray fill from weak natural wall bounce",
