      "setting": "Ordinary quiet private interior, not a designed set",
      "background_elements": "Low-saturation cool blue-gray walls, simple wall-to-ceiling transition, narrow dark edge of a cabinet/doorframe/furniture on image-right",
      "exposure": "Background approximately 1 to 2 stops darker than the subject"
    },
    "technical_quality": {
      "resolution": "4K",
      "quality": "Ultra-realistic RAW photo quality",
      "focus": "Sharp focus on the subject's face",
      "imperfections_to_retain": [
        "Flyaway hair",
        "Slightly displaced neckline",
        "Subtle phone camera sharpening",
        "Tiny digital noise",
        "Mild compression texture"
      ]
    }
